mapper.select:
SELECT COUNT(*) FROM call_record t
WHERE t.deleted = 0
  AND t.call_start_time >= #{start}
  AND t.call_start_time <= #{end}

SELECT COUNT(*) FROM call_record t
WHERE t.deleted = 0
  AND t.call_status = 2
  AND t.call_start_time >= #{start}
  AND t.call_start_time <= #{end}

SELECT COUNT(*) FROM call_record t
WHERE t.deleted = 0
  AND t.call_status = 3
  AND t.call_start_time >= #{start}
  AND t.call_start_time <= #{end}

SELECT COALESCE(SUM(t.call_duration), 0)
FROM call_record t
WHERE t.deleted = 0
  AND t.call_status = 2
  AND t.call_start_time >= #{start}
  AND t.call_start_time <= #{end}

SELECT COUNT(*) FROM call_record t
WHERE t.deleted = 0
  AND t.call_status = 2
  AND t.quality_status = 2
  AND t.call_start_time >= #{start}
  AND t.call_start_time <= #{end}
